-- Token-level anomaly profile for AGGNE.DEV.PER_COM_PAYLOAD (Motor).
-- Plain query, no procedure — paste and run directly.
-- For each token: NON_NULL / DISTINCT / NULL / BLANK / ZERO counts across all rows, plus a FLAG
-- for columns that look suspicious. A flag is a starting point for investigation, not proof of a
-- bug — always check the source table before concluding a fix is needed.

WITH PROFILE AS (
    SELECT 'PUREPOLICYNUMBER' TOKEN, COUNT(PUREPOLICYNUMBER) NON_NULL, COUNT(DISTINCT PUREPOLICYNUMBER) DISTINCT_VALS, SUM(CASE WHEN PUREPOLICYNUMBER IS NULL THEN 1 ELSE 0 END) NULL_CNT, SUM(CASE WHEN PUREPOLICYNUMBER IS NOT NULL AND TRIM(CAST(PUREPOLICYNUMBER AS VARCHAR))='' THEN 1 ELSE 0 END) BLANK_CNT, SUM(CASE WHEN CAST(PUREPOLICYNUMBER AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) ZERO_CNT FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'COVERAGE', COUNT(COVERAGE), COUNT(DISTINCT COVERAGE), SUM(CASE WHEN COVERAGE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN COVERAGE IS NOT NULL AND TRIM(CAST(COVERAGE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(COVERAGE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'SUBCOV', COUNT(SUBCOV), COUNT(DISTINCT SUBCOV), SUM(CASE WHEN SUBCOV IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN SUBCOV IS NOT NULL AND TRIM(CAST(SUBCOV AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(SUBCOV AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'COM_CLAUSE', COUNT(COM_CLAUSE), COUNT(DISTINCT COM_CLAUSE), SUM(CASE WHEN COM_CLAUSE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN COM_CLAUSE IS NOT NULL AND TRIM(CAST(COM_CLAUSE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(COM_CLAUSE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
