    UNION ALL SELECT 'MVVALUEWITHOUTACCESSORIES', COUNT(MVVALUEWITHOUTACCESSORIES), COUNT(DISTINCT MVVALUEWITHOUTACCESSORIES), SUM(CASE WHEN MVVALUEWITHOUTACCESSORIES IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN MVVALUEWITHOUTACCESSORIES IS NOT NULL AND TRIM(CAST(MVVALUEWITHOUTACCESSORIES AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(MVVALUEWITHOUTACCESSORIES AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
