    UNION ALL SELECT 'MARKETVALUEDESCRIPTION', COUNT(MARKETVALUEDESCRIPTION), COUNT(DISTINCT MARKETVALUEDESCRIPTION), SUM(CASE WHEN MARKETVALUEDESCRIPTION IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN MARKETVALUEDESCRIPTION IS NOT NULL AND TRIM(CAST(MARKETVALUEDESCRIPTION AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(MARKETVALUEDESCRIPTION AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
