    UNION ALL SELECT 'RESTRICTIONOFDRIVERAGE', COUNT(RESTRICTIONOFDRIVERAGE), COUNT(DISTINCT RESTRICTIONOFDRIVERAGE), SUM(CASE WHEN RESTRICTIONOFDRIVERAGE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN RESTRICTIONOFDRIVERAGE IS NOT NULL AND TRIM(CAST(RESTRICTIONOFDRIVERAGE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(RESTRICTIONOFDRIVERAGE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'VOLUNTARYEXCESS', COUNT(VOLUNTARYEXCESS), COUNT(DISTINCT VOLUNTARYEXCESS), SUM(CASE WHEN VOLUNTARYEXCESS IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN VOLUNTARYEXCESS IS NOT NULL AND TRIM(CAST(VOLUNTARYEXCESS AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(VOLUNTARYEXCESS AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'PROTECTIONTYPE', COUNT(PROTECTIONTYPE), COUNT(DISTINCT PROTECTIONTYPE), SUM(CASE WHEN PROTECTIONTYPE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN PROTECTIONTYPE IS NOT NULL AND TRIM(CAST(PROTECTIONTYPE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(PROTECTIONTYPE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'VEHICLETYPE', COUNT(VEHICLETYPE), COUNT(DISTINCT VEHICLETYPE), SUM(CASE WHEN VEHICLETYPE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN VEHICLETYPE IS NOT NULL AND TRIM(CAST(VEHICLETYPE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(VEHICLETYPE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'DESCRIPTION', COUNT(DESCRIPTION), COUNT(DISTINCT DESCRIPTION), SUM(CASE WHEN DESCRIPTION IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN DESCRIPTION IS NOT NULL AND TRIM(CAST(DESCRIPTION AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(DESCRIPTION AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'NUMBEROFCYLINDERS', COUNT(NUMBEROFCYLINDERS), COUNT(DISTINCT NUMBEROFCYLINDERS), SUM(CASE WHEN NUMBEROFCYLINDERS IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN NUMBEROFCYLINDERS IS NOT NULL AND TRIM(CAST(NUMBEROFCYLINDERS AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(NUMBEROFCYLINDERS AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'DRIVEDESCRIPTION', COUNT(DRIVEDESCRIPTION), COUNT(DISTINCT DRIVEDESCRIPTION), SUM(CASE WHEN DRIVEDESCRIPTION IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN DRIVEDESCRIPTION IS NOT NULL AND TRIM(CAST(DRIVEDESCRIPTION AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(DRIVEDESCRIPTION AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'INDUCTIONTYPE', COUNT(INDUCTIONTYPE), COUNT(DISTINCT INDUCTIONTYPE), SUM(CASE WHEN INDUCTIONTYPE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN INDUCTIONTYPE IS NOT NULL AND TRIM(CAST(INDUCTIONTYPE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(INDUCTIONTYPE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'IMPORTFLAG', COUNT(IMPORTFLAG), COUNT(DISTINCT IMPORTFLAG), SUM(CASE WHEN IMPORTFLAG IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN IMPORTFLAG IS NOT NULL AND TRIM(CAST(IMPORTFLAG AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(IMPORTFLAG AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'MARKETVALUEWITHACCESSORIESAMOUNT', COUNT(MARKETVALUEWITHACCESSORIESAMOUNT), COUNT(DISTINCT MARKETVALUEWITHACCESSORIESAMOUNT), SUM(CASE WHEN MARKETVALUEWITHACCESSORIESAMOUNT IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN MARKETVALUEWITHACCESSORIESAMOUNT IS NOT NULL AND TRIM(CAST(MARKETVALUEWITHACCESSORIESAMOUNT AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(MARKETVALUEWITHACCESSORIESAMOUNT AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'AGREEDVALUEAMOUNT', COUNT(AGREEDVALUEAMOUNT), COUNT(DISTINCT AGREEDVALUEAMOUNT), SUM(CASE WHEN AGREEDVALUEAMOUNT IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN AGREEDVALUEAMOUNT IS NOT NULL AND TRIM(CAST(AGREEDVALUEAMOUNT AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(AGREEDVALUEAMOUNT AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'ADDDETAILSFORTHEINTERESTEDPARTY', COUNT(ADDDETAILSFORTHEINTERESTEDPARTY), COUNT(DISTINCT ADDDETAILSFORTHEINTERESTEDPARTY), SUM(CASE WHEN ADDDETAILSFORTHEINTERESTEDPARTY IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN ADDDETAILSFORTHEINTERESTEDPARTY IS NOT NULL AND TRIM(CAST(ADDDETAILSFORTHEINTERESTEDPARTY AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(ADDDETAILSFORTHEINTERESTEDPARTY AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'HIRECARHIREAFTERINCIDENT', COUNT(HIRECARHIREAFTERINCIDENT), COUNT(DISTINCT HIRECARHIREAFTERINCIDENT), SUM(CASE WHEN HIRECARHIREAFTERINCIDENT IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN HIRECARHIREAFTERINCIDENT IS NOT NULL AND TRIM(CAST(HIRECARHIREAFTERINCIDENT AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(HIRECARHIREAFTERINCIDENT AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'CHOICEOFREPAIR', COUNT(CHOICEOFREPAIR), COUNT(DISTINCT CHOICEOFREPAIR), SUM(CASE WHEN CHOICEOFREPAIR IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN CHOICEOFREPAIR IS NOT NULL AND TRIM(CAST(CHOICEOFREPAIR AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(CHOICEOFREPAIR AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'EXCESSWAIVERFORGLASS', COUNT(EXCESSWAIVERFORGLASS), COUNT(DISTINCT EXCESSWAIVERFORGLASS), SUM(CASE WHEN EXCESSWAIVERFORGLASS IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN EXCESSWAIVERFORGLASS IS NOT NULL AND TRIM(CAST(EXCESSWAIVERFORGLASS AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(EXCESSWAIVERFORGLASS AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'AVVALUEWITHOUTACCESSORIES', COUNT(AVVALUEWITHOUTACCESSORIES), COUNT(DISTINCT AVVALUEWITHOUTACCESSORIES), SUM(CASE WHEN AVVALUEWITHOUTACCESSORIES IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN AVVALUEWITHOUTACCESSORIES IS NOT NULL AND TRIM(CAST(AVVALUEWITHOUTACCESSORIES AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(AVVALUEWITHOUTACCESSORIES AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'PMCLMINCD', COUNT(PMCLMINCD), COUNT(DISTINCT PMCLMINCD), SUM(CASE WHEN PMCLMINCD IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN PMCLMINCD IS NOT NULL AND TRIM(CAST(PMCLMINCD AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(PMCLMINCD AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'PMCLMCNT', COUNT(PMCLMCNT), COUNT(DISTINCT PMCLMCNT), SUM(CASE WHEN PMCLMCNT IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN PMCLMCNT IS NOT NULL AND TRIM(CAST(PMCLMCNT AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(PMCLMCNT AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'PMEXPPREM', COUNT(PMEXPPREM), COUNT(DISTINCT PMEXPPREM), SUM(CASE WHEN PMEXPPREM IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN PMEXPPREM IS NOT NULL AND TRIM(CAST(PMEXPPREM AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(PMEXPPREM AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
