    UNION ALL SELECT 'POWERKW', COUNT(POWERKW), COUNT(DISTINCT POWERKW), SUM(CASE WHEN POWERKW IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN POWERKW IS NOT NULL AND TRIM(CAST(POWERKW AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(POWERKW AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'TRACKREAR', COUNT(TRACKREAR), COUNT(DISTINCT TRACKREAR), SUM(CASE WHEN TRACKREAR IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN TRACKREAR IS NOT NULL AND TRIM(CAST(TRACKREAR AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(TRACKREAR AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
    UNION ALL SELECT 'LOAD_DATE', COUNT(LOAD_DATE), COUNT(DISTINCT LOAD_DATE), SUM(CASE WHEN LOAD_DATE IS NULL THEN 1 ELSE 0 END), SUM(CASE WHEN LOAD_DATE IS NOT NULL AND TRIM(CAST(LOAD_DATE AS VARCHAR))='' THEN 1 ELSE 0 END), SUM(CASE WHEN CAST(LOAD_DATE AS VARCHAR) IN ('0','0.00') THEN 1 ELSE 0 END) FROM AGGNE.DEV.PER_COM_PAYLOAD
),
TOTALS AS (
    SELECT COUNT(*) AS TOTAL_ROWS FROM AGGNE.DEV.PER_COM_PAYLOAD
)
SELECT
    P.TOKEN,
    T.TOTAL_ROWS,
    P.NON_NULL,
    P.DISTINCT_VALS,
    P.NULL_CNT,
    P.BLANK_CNT,
    P.ZERO_CNT,
    ROUND((P.NULL_CNT + P.BLANK_CNT) / NULLIF(T.TOTAL_ROWS,0) * 100, 1) AS MISSING_PCT,
    ARRAY_TO_STRING(ARRAY_CONSTRUCT_COMPACT(
        CASE WHEN P.DISTINCT_VALS <= 1 THEN 'SINGLE-VALUE' END,
        CASE WHEN (P.NULL_CNT + P.BLANK_CNT) / NULLIF(T.TOTAL_ROWS,0) * 100 >= 90 THEN 'MOSTLY-MISSING' END,
        CASE WHEN P.ZERO_CNT / NULLIF(T.TOTAL_ROWS,0) >= 0.90 THEN 'MOSTLY-ZERO' END
    ), ',') AS FLAG
FROM PROFILE P
CROSS JOIN TOTALS T
ORDER BY P.TOKEN;
